public static class SteelCargoAssetBuilder {
 const string Root="Assets/_Anseong/Art/Environment/Assets/SteelCargo";
 static Material paint,steel,dark,amber;static readonly List<GameObject> chunks=new List<GameObject>();
 static void Folder(string path){if(AssetDatabase.IsValidFolder(path))return;string parent=Path.GetDirectoryName(path).Replace('\\','/');Folder(parent);AssetDatabase.CreateFolder(parent,Path.GetFileName(path));}
 static Material Mat(string name,Color color,float metallic=0){var m=AssetDatabase.LoadAssetAtPath<Material>(Root+"/"+name+".mat");if(m)return m;m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.color=color;m.SetFloat("_Metallic",metallic);m.SetFloat("_Smoothness",.25f);m.enableInstancing=true;AssetDatabase.CreateAsset(m,Root+"/"+name+".mat");return m;}
 static void Box(Transform root,string name,Vector3 pos,Vector3 size,Material mat){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(root,false);g.transform.localPosition=pos;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;Object.DestroyImmediate(g.GetComponent<Collider>());chunks.Add(g);}
 static Mesh Ring(int sides,float outer,float inner,float length){var v=new List<Vector3>();var t=new List<int>();Vector3 P(int i,float radius,float x){float a=i*2*Mathf.PI/sides;return new Vector3(x,Mathf.Cos(a)*radius,Mathf.Sin(a)*radius);}void Q(Vector3 a,Vector3 b,Vector3 c,Vector3 d){int n=v.Count;v.AddRange(new[]{a,b,c,d});t.AddRange(new[]{n,n+1,n+2,n,n+2,n+3});}for(int i=0;i<sides;i++){Q(P(i,outer,-length/2),P(i+1,outer,-length/2),P(i+1,outer,length/2),P(i,outer,length/2));Q(P(i,inner,length/2),P(i+1,inner,length/2),P(i+1,inner,-length/2),P(i,inner,-length/2));Q(P(i,outer,length/2),P(i+1,outer,length/2),P(i+1,inner,length/2),P(i,inner,length/2));Q(P(i,inner,-length/2),P(i+1,inner,-length/2),P(i+1,outer,-length/2),P(i,outer,-length/2));}var mesh=new Mesh();mesh.SetVertices(v);mesh.SetTriangles(t,0);mesh.RecalculateNormals();return mesh;}
 static void Tube(Transform root,string name,Vector3 pos,Mesh mesh,Material mat){var g=new GameObject(name);g.transform.SetParent(root,false);g.transform.localPosition=pos;g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=mat;chunks.Add(g);}
 static Mesh Bake(Transform root){var materials=new[]{paint,steel,dark,amber};var groups=new List<Mesh>();var final=new CombineInstance[4];for(int i=0;i<4;i++){var list=new List<CombineInstance>();foreach(var part in chunks)if(part.GetComponent<Renderer>().sharedMaterial==materials[i])list.Add(new CombineInstance{mesh=part.GetComponent<MeshFilter>().sharedMesh,transform=root.worldToLocalMatrix*part.transform.localToWorldMatrix});var m=new Mesh();m.CombineMeshes(list.ToArray(),true,true);groups.Add(m);final[i]=new CombineInstance{mesh=m,transform=Matrix4x4.identity};}var result=new Mesh{name="SteelCargo_LowPoly"};result.CombineMeshes(final,false,true);result.RecalculateBounds();foreach(var m in groups)Object.DestroyImmediate(m);return result;}
 static int Save(GameObject root,string name){var mesh=Bake(root.transform);mesh.name=name;string path=Root+"/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(mesh,old);Object.DestroyImmediate(mesh);mesh=old;}else AssetDatabase.CreateAsset(mesh,path);foreach(var g in chunks)Object.DestroyImmediate(g);chunks.Clear();root.AddComponent<MeshFilter>().sharedMesh=mesh;root.AddComponent<MeshRenderer>().sharedMaterials=new[]{paint,steel,dark,amber};var collider=root.AddComponent<BoxCollider>();collider.center=mesh.bounds.center;collider.size=mesh.bounds.size;var prefab=PrefabUtility.SaveAsPrefabAsset(root,Root+"/"+name+".prefab");int tris=mesh.triangles.Length/3;if(tris>1200||Mathf.Abs(mesh.bounds.min.y)>.025f||prefab.GetComponentsInChildren<Rigidbody>().Length!=0||prefab.GetComponentsInChildren<MonoBehaviour>().Length!=0)throw new Exception("Cargo validation failed: "+name);Debug.Log("STEEL_CARGO_TEST_PASS "+name+" triangles="+tris+" size="+mesh.bounds.size);Object.DestroyImmediate(root);return tris;}
 [MenuItem("Anseong/Art/Build Steel Cargo")]
 public static void Build(){Folder(Root);paint=Mat("TimberBearers",new Color(.32f,.24f,.14f));steel=Mat("Steel",new Color(.34f,.38f,.39f),.55f);dark=Mat("Straps",new Color(.065f,.09f,.1f));amber=Mat("OxideEdges",new Color(.32f,.17f,.10f));chunks.Clear();
  var root=new GameObject("SteelCoil");var r=root.transform;for(int side=-1;side<=1;side+=2){Box(r,"TimberFoot",new Vector3(side*.7f,.12f,0),new Vector3(.3f,.24f,2.1f),paint);Box(r,"Saddle",new Vector3(0,.37f,side*.6f),new Vector3(2.1f,.3f,.34f),paint);chunks[chunks.Count-1].transform.localRotation=Quaternion.Euler(side*-22,0,0);}var coil=Ring(24,1,.32f,1.8f);Tube(r,"Coil",new Vector3(0,1.3f,0),coil,steel);var band=Ring(24,1.014f,.998f,.055f);for(int side=-1;side<=1;side+=2)Tube(r,"SecuringBand",new Vector3(side*.56f,1.3f,0),band,dark);Box(r,"OxideMark",new Vector3(.904f,1.3f,.62f),new Vector3(.012f,.12f,.25f),amber);int count=Save(root,"SteelCoil");Object.DestroyImmediate(coil);Object.DestroyImmediate(band);
  root=new GameObject("SteelSlabStack");r=root.transform;foreach(float z in new[]{-2.3f,0,2.3f})Box(r,"TimberBearer",new Vector3(0,.13f,z),new Vector3(2.7f,.26f,.3f),paint);for(int i=0;i<4;i++){Box(r,"Slab",new Vector3((i%2)*.04f,.26f+.17f+i*.36f,0),new Vector3(2.4f,.34f,6),steel);Box(r,"OxidizedEnd",new Vector3((i%2)*.04f,.26f+.17f+i*.36f,-3.006f),new Vector3(2.4f,.075f,.012f),amber);}foreach(float z in new[]{-1.8f,1.8f}){Box(r,"TopStrap",new Vector3(0,1.69f,z),new Vector3(2.47f,.025f,.045f),dark);for(int side=-1;side<=1;side+=2)Box(r,"SideStrap",new Vector3(side*1.235f,.97f,z),new Vector3(.025f,1.42f,.045f),dark);}count+=Save(root,"SteelSlabStack");
  root=new GameObject("SteelBeamBundle");r=root.transform;foreach(float z in new[]{-2.3f,2.3f})Box(r,"TimberBearer",new Vector3(0,.12f,z),new Vector3(2,.24f,.3f),paint);for(int row=0;row<2;row++)for(int col=0;col<4;col++){float x=(col-1.5f)*.42f,y=.24f+.18f+row*.36f;foreach(float offset in new[]{-.15f,.15f})Box(r,"HBeamFlange",new Vector3(x,y+offset,0),new Vector3(.36f,.06f,6.5f),steel);Box(r,"HBeamWeb",new Vector3(x,y,0),new Vector3(.055f,.3f,6.5f),steel);Box(r,"OxideEnd",new Vector3(x,y+.151f,-3.256f),new Vector3(.36f,.055f,.012f),amber);}foreach(float z in new[]{-1.9f,1.9f}){Box(r,"TopBand",new Vector3(0,.965f,z),new Vector3(1.7f,.025f,.05f),dark);for(int side=-1;side<=1;side+=2)Box(r,"SideBand",new Vector3(side*.85f,.61f,z),new Vector3(.025f,.72f,.05f),dark);}count+=Save(root,"SteelBeamBundle");
  var group=new GameObject("SteelCargo_Group");void Place(string name,Vector3 pos){var p=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/"+name+".prefab"));p.transform.SetParent(group.transform,false);p.transform.localPosition=pos;}Place("SteelSlabStack",new Vector3(-4.5f,0,0));Place("SteelBeamBundle",new Vector3(0,0,0));Place("SteelCoil",new Vector3(4.3f,0,-1.5f));Place("SteelCoil",new Vector3(4.3f,0,1.6f));var groupPrefab=PrefabUtility.SaveAsPrefabAsset(group,Root+"/SteelCargo_Group.prefab");Object.DestroyImmediate(group);
  Folder("Assets/_Anseong/Scenes/Sandbox");EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects,NewSceneMode.Single);PrefabUtility.InstantiatePrefab(groupPrefab);var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.name="PreviewGround";floor.transform.position=new Vector3(0,-.1f,0);floor.transform.localScale=new Vector3(80,.2f,80);floor.GetComponent<Renderer>().sharedMaterial=Mat("PreviewGround",new Color(.18f,.20f,.21f));var camera=Camera.main;camera.transform.position=new Vector3(14,10,16);camera.transform.LookAt(new Vector3(0,.8f,0));camera.fieldOfView=40;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.25f,.34f,.42f);var sun=Object.FindFirstObjectByType<Light>();sun.intensity=2;sun.transform.rotation=Quaternion.Euler(45,-35,0);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.65f,.68f,.72f);EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/_Anseong/Scenes/Sandbox/Sandbox_SteelCargo.unity");AssetDatabase.SaveAssets();Capture(camera,"SteelCargo_Preview");Debug.Log("STEEL_CARGO_BUILD_PASS uniqueTriangles="+count+" prefabTypes=3 sharedMaterials=4 textures=0 rigidbodies=0");
 }
 static void Capture(Camera camera,string name){var texture=new RenderTexture(1200,800,24);var previous=RenderTexture.active;camera.targetTexture=texture;camera.Render();RenderTexture.active=texture;var image=new Texture2D(1200,800,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1200,800),0,0);image.Apply();File.WriteAllBytes("C:/Users/Admin/Documents/ChatGPT/안성제철/output/"+name+".png",image.EncodeToPNG());camera.targetTexture=null;RenderTexture.active=previous;Object.DestroyImmediate(image);Object.DestroyImmediate(texture);}
